// Porous Bone - PARAMETRIC texture (u,v). Static.
// Parametric surfaces have NO displacement: the geometry stays smooth, so the
// holes are PAINTED. To make them read as real cavities the snippet fakes the
// relief: it computes the hole field, then shades it with an analytic gradient
// (a cheap bump) so each rim catches a highlight on one side and a shadow on
// the other, exactly as the ray-marching version gets for free from the engine.
// In scope: u, v (already zoom/pan/rotation transformed), u_col1, u_col2.
// Dock colors: u_col1 = shell (light), u_col2 = hole interior (warm dark).

float DENSITY   = 14.0;  // hole density (cells across the sheet) [6 .. 26]
float R_MIN     = 0.10;  // smallest hole radius                  [0.05 .. 0.20]
float R_MAX     = 0.46;  // largest  hole radius                  [0.30 .. 0.55]
float SIZE_BIAS = 2.2;   // >1 = many small, few big holes        [1.0 .. 4.0]
float FILL      = 0.82;  // fraction of cells that get a hole     [0.5 .. 1.0]
float RIM       = 0.10;  // rim softness                          [0.04 .. 0.20]
float RELIEF    = 2.6;   // strength of the fake relief           [0.0 .. 5.0]
float GRAIN     = 0.10;  // micro speckle on the shell            [0.0 .. 0.25]

// Light direction for the fake relief (upper-left, like the reference photos).
vec2 LDIR = normalize(vec2(-0.6, 0.8));

vec2 P = vec2(u, v) * DENSITY;

// The hole field is sampled 3 times (centre + 2 neighbours) to get its gradient
// by finite differences -> that gradient is the fake surface normal.
float EPS = 0.035;

float fld[3];

for (int s = 0; s < 3; s++) {
    // s=0 centre, s=1 shifted in x, s=2 shifted in y
    vec2 sp = P;
    if (s == 1) sp.x += EPS;
    if (s == 2) sp.y += EPS;

    vec2 vi = floor(sp);
    vec2 vf = fract(sp);

    float hole = 8.0;

    for (int gx = -1; gx <= 1; gx++)
    for (int gy = -1; gy <= 1; gy++) {
        vec2 g = vec2(float(gx), float(gy));
        vec2 c = vi + g;

        // same 3 randoms as the ray-marching version: offset, radius, existence
        vec2 o = fract(sin(vec2(
            dot(c, vec2(127.1, 311.7)),
            dot(c, vec2(269.5, 183.3)))) * 43758.5453);

        float rr = fract(sin(dot(c, vec2(419.2, 371.9))) * 24634.6345);
        float ex = fract(sin(dot(c, vec2(157.3, 113.7))) * 15731.7431);

        float rad = mix(R_MIN, R_MAX, safePow(rr, SIZE_BIAS));
        rad *= step(1.0 - FILL, ex);

        hole = min(hole, length(g + o - vf) - rad);
    }

    fld[s] = hole;
}

float hole = fld[0];

// 1 inside a hole, 0 on the shell.
float inHole = 1.0 - smoothstep(-0.02, RIM, hole);

// --- FAKE RELIEF: gradient of the hole field = slope of the rim.
// Positive where the wall descends toward the light, negative on the far side.
vec2 grad = vec2(fld[1] - fld[0], fld[2] - fld[0]) / EPS;

// only the rims are lit: flat areas (inside and far outside) have zero gradient
float rimBand = exp(-safePow(hole / RIM, 2.0) * 2.0);
float lambert = dot(normalize(grad + vec2(0.0, 1e-5)), LDIR);
float relief  = lambert * rimBand * RELIEF * 0.18;

// --- micro-grain, keeps the white from looking like plastic.
vec2 gp = vec2(u, v) * 260.0;
vec2 gi = floor(gp);
vec2 gf = gp - gi;
vec2 gw = gf * gf * (3.0 - 2.0 * gf);

float g00 = fract(sin(dot(gi + vec2(0.0, 0.0), vec2(127.1, 311.7))) * 43758.5453);
float g10 = fract(sin(dot(gi + vec2(1.0, 0.0), vec2(127.1, 311.7))) * 43758.5453);
float g01 = fract(sin(dot(gi + vec2(0.0, 1.0), vec2(127.1, 311.7))) * 43758.5453);
float g11 = fract(sin(dot(gi + vec2(1.0, 1.0), vec2(127.1, 311.7))) * 43758.5453);

float grain = mix(mix(g00, g10, gw.x), mix(g01, g11, gw.x), gw.y) - 0.5;

// --- composition
vec3 col = u_col1 * (1.0 + GRAIN * grain);

// darken toward u_col2 in the cavities; deeper holes go darker (radius-aware
// falloff: the field is more negative at the centre of a big hole).
float depth = clamp(-hole / RIM, 0.0, 1.0);
col = mix(col, u_col2, inHole * (0.55 + 0.40 * depth));

// the fake relief goes on TOP: bright lip on the light side, shadow opposite.
col *= (1.0 + relief);

return clamp(col, 0.0, 1.0);
